mapper.select:
select us.USERTYPE,us.RYJBXXBS,us.RYBM,us.XM,us.SZDZBDM,us.RYZT,us.SQRDRQ, -- us.ZWMC, uszw.dnzw as ZWMC, us.DNZWMC,us.XJSZWMC,us.XB,us.JG,us.MZ,us.CSRQ,us.XL,us.SFZH, p.DZZMC, ryzt.HZMC as RYZTMC, xb.HZMC as XBMC,mz.HZMC as MZMC,xl.HZMC as XLMC,jszw.HZMC as JSZWMC, userinfo.USERNAME as MOBILE,us.DNZWMC as POST, dj.JRZGZZRQ as RDSJ, usfb.NL AS AGE, uszw.DNZW as DNZW, usfb.SFSLDRY, ifnull(usfb.LEADTYPE,0) as LEADTYPE, userinfo.USERNAME as userNo,usfb.gradeName,usfb.className,usfb.enrollmentDate,usfb.graduateDate,usfb.workDate,usfb.mobile as contactMobile, usfb.technologyPosition, usfb.isStudent,case when usfb.isStudent=1 then '是' else '否' end as isStudentName from VM_RYJBXX us -- 视图 left join RS_RYJBXXFB usfb on us.RYBM=usfb.RYBM inner join ZZ_ZZQKXX p on us.SZDZBDM=p.DZZDM -- 党组织信息 left join ZZ_ZZQKXXFB fb on p.DZZDM=fb.DZZDM left join Zzzd_ryzt ryzt on us.RYZT=ryzt.BM -- 人员状态 left join zd_xbm xb on us.XB=xb.BM -- 性别 left join zd_mzdm mz on us.MZ=mz.BM -- 民族 left join zd_whcddm1 xl on us.XL=xl.BM -- 学历 left join zd_zyjszwdm jszw on us.XJSZWMC=jszw.BM -- 技术专业职务 left join CF_USERS userinfo on us.RYBM=userinfo.USERID left join ZZ_DJXX dj on us.RYBM=dj.RYBM left join vw_partyduty uszw on us.RYBM=uszw.RYBM -- 党内职务名称 left join ZZ_ZZQKXX dw on SUBSTR(p.DZZDM,1,12)=dw.DZZDM left join VM_PARTYGROUP partyGroup on dw.DZZDM = partyGroup.DZZDM where 1=1
and p.DZZDM like concat(#{dzzdm},'%')
and us.RYBM = #{rybm}
and us.XM like concat('%',#{xm},'%')
and fb.ZZLB = #{zzlb}
and us.XB = #{xb}
and us.ZWJB = #{zwjb}
and dj.JRZGZZRQ >= #{sqrdrq_begin}
and dj.JRZGZZRQ <= #{sqrdrq_end}
and p.DZZMC like concat('%',#{szdzb},'%')
and us.RYJBXXBS in
#{userId}
and us.RYZT in
#{ryzt}
and us.RYJBXXBS not in
#{userId}
and us.SZDZBDM = #{szdzbdm}
and us.RYBM not in
#{rybm}
and us.RYBM in
#{rybm}
and SUBSTR(p.DZZDM,1,12) in(select DZZDM from ZZ_DZZFBQK where ZZFB= #{zzfbType})
and us.MZ = #{mz}
and uszw.DNZW like concat('%',#{dnzw},'%')
and us.XL = #{xl}
and usfb.NL >= #{age_begin}
and usfb.NL <= #{age_end}
/*是否属领导人员*/ and usfb.SFSLDRY = #{sfsldry}
and us.ZWMC like concat('%',#{zwmc},'%')
/*是否在岗*/
and (us.GZGW not in('0500','0501','0502','0504') or us.GZGW is null)
and us.GZGW in('0500','0501','0502','0504')
and fb.JCZZFL = #{jczzfl}
and partyGroup.GROUPID like concat('%',#{partyGroupId},'%')
and userinfo.USERNAME like concat('%',#{mobile},'%')
and us.sfzh like concat('%',#{sfzh},'%')
and usfb.isStudent = #{isStudent}
and (usfb.isStudent = #{isStudent} or usfb.isStudent is null)
and userinfo.USERNAME in (select no from lw_leaderteam where leaderTeamType=#{leaderTeamUserType})
order by CONVERT(us.XM USING gbk),us.RYJBXXBS

select us.USERTYPE,us.RYJBXXBS,us.RYBM,us.XM,us.SZDZBDM,us.RYZT,us.SQRDRQ, uszw.dnzw as ZWMC, us.DNZWMC,us.XJSZWMC,us.XB,us.JG,us.MZ,us.CSRQ,us.XL,us.SFZH, p.DZZMC, ryzt.HZMC as RYZTMC, xb.HZMC as XBMC,mz.HZMC as MZMC,xl.HZMC as XLMC,jszw.HZMC as JSZWMC, userinfo.USERNAME as MOBILE,us.DNZWMC as POST, dj.JRZGZZRQ as RDSJ, usfb.NL AS AGE, uszw.DNZW as DNZW, usfb.SFSLDRY, ifnull(usfb.LEADTYPE,0) as LEADTYPE, userinfo.USERNAME as userNo,usfb.gradeName,usfb.className,usfb.enrollmentDate,usfb.graduateDate,usfb.workDate,usfb.mobile as contactMobile, usfb.technologyPosition,userinfo.roleName from vm_ryjbxx_all us -- 视图 left join RS_RYJBXXFB usfb on us.RYBM=usfb.RYBM inner join ZZ_ZZQKXX p on us.SZDZBDM=p.DZZDM -- 党组织信息 left join ZZ_ZZQKXXFB fb on p.DZZDM=fb.DZZDM left join Zzzd_ryzt ryzt on us.RYZT=ryzt.BM -- 人员状态 left join zd_xbm xb on us.XB=xb.BM -- 性别 left join zd_mzdm mz on us.MZ=mz.BM -- 民族 left join zd_whcddm1 xl on us.XL=xl.BM -- 学历 left join zd_zyjszwdm jszw on us.XJSZWMC=jszw.BM -- 技术专业职务 left join ZZ_DJXX dj on us.RYBM=dj.RYBM left join vw_partyduty uszw on us.RYBM=uszw.RYBM -- 党内职务名称 left join (select us.USERID,us.USERNAME,GROUP_CONCAT(cr.ROLENAME SEPARATOR '、') as roleName from cf_users us left join cf_userroles cu on us.USERID = cu.USERID left join cf_roles cr on cu.ROLEID = cr.ROLEID group by us.USERID,us.USERNAME) userinfo on us.RYBM = userinfo.USERID where 1=1
and p.DZZDM like concat(#{dzzdm},'%')
and us.SZDZBDM = #{szdzbdm}
and fb.ZZLB = #{zzlb}
and us.RYBM = #{rybm}
and us.XM like concat('%',#{xm},'%')
and us.XB = #{xb}
and us.MZ = #{mz}
and us.XL = #{xl}
and userinfo.USERNAME like concat('%',#{mobile},'%')
and us.RYZT in
#{ryzt}
and userinfo.USERNAME like concat('%',#{userNo},'%')
order by CONVERT(us.XM USING gbk),us.RYJBXXBS

select distinct us.RYJBXXBS,us.RYBM,us.SZDZBDM,p.DZZMC, b.XM,zwmc.hzmc as ZWMC,t1.JC, us.SFZH ,xb.HZMC as XBMC,us.JG from ZZ_BZCYXX b inner join ( select c.dzzdm,max(cast(c.jc as SIGNED INTEGER)) jc from ZZ_BZCYXX c group by c.dzzdm) t1 on b.dzzdm=t1.dzzdm and b.jc=t1.jc inner join vm_ryjbxx us on b.rybm=us.rybm inner join ZZ_ZZQKXX p on us.szdzbdm=p.dzzdm left join Zzzd_zwmc zwmc on b.zwmc = zwmc.bm left join zd_xbm xb on us.xb=xb.bm -- 性别 where zwmc.hzmc in('总支书记','总支副书记','总支委员','支部书记','支部副书记','支部委员') and us.ryzt in('2','3') -- 预备党员,正式党员
and b.dzzdm like concat('',#{dzzdm},'%')
and b.dzzdm = #{szdzbdm}
and us.rybm like concat('%',#{rybm},'%')
and b.xm like concat('%',#{xm},'%')
and us.ryjbxxbs in
#{userId}
and us.ryjbxxbs not in
#{userId}
and us.rybm not in
#{rybm}
order by us.szdzbdm

select p.*,pyjg.HZMC as pyjgmc from ZZ_MZPYXX p left join ZZZD_PYJG pyjg on p.PYJG=pyjg.BM where 1=1
and p.rybm = #{rybm}
order by p.KZPYRQ desc

select pxqk.*,pxdd.HZMC as PXDDMC,xs.HZMC as PXXSMC,mc.hzmc as PXMCMZ,jg.HZMC as PXJGMZ from ZZ_PXQK pxqk left join ZZZD_PXDDDM pxdd on pxqk.PXDD = pxdd.bm left join ZZZD_PXXSDM xs on pxqk.PXXS=xs.bm left join ZZZD_PXMC mc on pxqk.PXMC=mc.bm left join ZZZD_PXJG jg on pxqk.PXJG=jg.bm where 1=1
and pxqk.rybm = #{rybm}
order by pxqk.PXKSSJ desc

select us.USERTYPE,us.RYJBXXBS,us.RYBM,us.XM,us.SZDZBDM,us.RYZT,us.SQRDRQ,
us.ZWMC,us.DNZWMC,us.XJSZWMC,us.XB,us.JG,us.MZ,us.CSRQ,us.XL,us.SFZH,
p.DZZMC,
ryzt.HZMC as RYZTMC,
xb.HZMC as XBMC,mz.HZMC as MZMC,xl.HZMC as XLMC,jszw.HZMC as JSZWMC,
dj.JRZGZZRQ as RDSJ,
usfb.NL AS AGE,
uszw.DNZW as DNZW,
usfb.SFZG,
dj.ZZRQ,
if(jlcf.USERID,1,0) as SFZYXQ,
dw.DZZDM as DWDM,dw.DZZMC as DWMC
from VM_RYJBXX us -- 视图
left join RS_RYJBXXFB usfb on us.RYBM=usfb.RYBM
inner join ZZ_ZZQKXX p on us.szdzbdm=p.dzzdm -- 党组织信息
inner join ZZ_ZZQKXX dw on SUBSTR(us.szdzbdm,1,12) = dw.DZZDM -- 党委信息
left join ZZ_ZZQKXXFB fb on p.DZZDM=fb.DZZDM
left join Zzzd_ryzt ryzt on us.ryzt=ryzt.bm -- 人员状态
left join zd_xbm xb on us.xb=xb.bm -- 性别
left join zd_mzdm mz on us.mz=mz.bm -- 民族
left join zd_whcddm1 xl on us.xl=xl.bm -- 学历
left join zd_zyjszwdm jszw on us.xjszwmc=jszw.bm -- 技术专业职务
left join ZZ_DJXX dj on us.RYBM=dj.RYBM
left join vw_partyduty uszw on us.rybm=uszw.rybm -- 党内职务名称
left join (
select USERID from DJ_JLCFXX j where j.YXKSRQ  <=  CURDATE() and j.YXJSRQ  >=  CURDATE() group
by USERID
) jlcf on us.RYBM=jlcf.USERID
where 1=1

    and p.dzzdm like concat('',#{dzzdm},'%')


    and p.dzzmc like concat('%',#{dzzmc},'%')


    and us.xm like concat('%',#{xm},'%')


    and us.csrq  >=  #{csrq_begin}


    and us.csrq  <=  #{csrq_end}


    and usfb.NL  >=  #{age_begin}


    and usfb.NL  <=  #{age_end}


    and dj.jrzgzzrq  >=  #{rdsj_begin}


    and dj.jrzgzzrq  <=  #{rdsj_end}


    and dj.zzrq  >=  #{zzsj_begin}


    and dj.zzrq  <=  #{zzsj_end}


    and us.jg like concat('%',#{jg},'%')



    and uszw.dnzw in

        #{dnzw}




    and

        us.zwmc like concat('%',#{xzzw},'%')




    and us.xjszwmc in

        #{jszw}




    and us.xl in

        #{xl}




    and us.xb in

        #{xb}




    and usfb.SFZG in

        #{gwzt}




    and us.ryzt in

        #{zzmm}




    and us.mz in

        #{mz}




    and us.RYBM in
    (
    select pxry.USERID from DJ_DNPXXX dnpx
    inner join DJ_DNPXRY pxry on dnpx.ID=pxry.DNPXID
    where 1=1

        and date_format(dnpx.honourtime,'%Y') = #{pxpy_year}


        and dnpx.honourlevel = #{pxpy_level}


        and dnpx.honourtype in

            #{pxpy_type}


    )






        and jlcf.USERID is not null


        and jlcf.USERID is null


order by CONVERT(us.XM USING gbk),us.RYJBXXBS

select DICKEY as leaderType, d.DICVALUE as leaderTypeName, d.RYBM as rybm, d.XM as xm, ifnull(t.count, 0) as count, '1次/季' as totalTypeName, 1 as totalType, 1 as baseCount from ( select DICTYPEKEY,DICKEY,DICVALUE,RYBM,XM,XMPY,SZDZBDM from CF_DICTIONARY, VM_RYJBXX where DICTYPEKEY = 'leaderType' and DICKEY in (1, 3)
and RYBM = #{rybm}
) d left join (select u.USERCODE,u.LEADERTYPE,count(*) as count from US_USERLEADER U where 1 = 1
and u.USERCODE = #{rybm}
and date_format(LEADERTIME,'%Y') = #{year} and QUARTER(LEADERTIME) = #{quarter} group by u.USERCODE,u.LEADERTYPE ) t on d.dickey = t.LEADERTYPE and d.RYBM = t.USERCODE union select dickey as LEADERTYPE, d.DICVALUE as LEADERTYPENAME, d.RYBM, d.XM, ifnull(t.count, 0) as COUNT, '1次/年' as totalTypeName, 2 as totalType, 1 as baseCount from (select DICTYPEKEY,DICKEY,DICVALUE,RYBM,XM,XMPY,SZDZBDM from CF_DICTIONARY, VM_RYJBXX where DICTYPEKEY = 'leaderType' and DICKEY in (2, 4, 5, 7, 8)
and RYBM = #{rybm}
) d left join (select u.USERCODE,u.LEADERTYPE,count(*) as count from US_USERLEADER U where 1 = 1
and u.USERCODE = #{rybm}
and date_format(LEADERTIME,'%Y') = #{year} group by u.USERCODE,u.LEADERTYPE ) t on d.dickey = t.LEADERTYPE and d.RYBM = t.USERCODE union -- 落实联系点制度（直属机关党委2次/年，其他党委4次/年） select dickey as LEADERTYPE, d.DICVALUE as LEADERTYPENAME, d.RYBM, d.XM, ifnull(t.count, 0) as COUNT, (case when dw.DZZDM='001091209013' and dw2.zzlb not in('100') then '2次/年' else '4次/年' end)as totalTypeName, (case when dw.DZZDM='001091209013' and dw2.zzlb not in('100') then 3 else 4 end) as totalType, (case when dw.DZZDM='001091209013' and dw2.zzlb not in('100') then 2 else 4 end) as baseCount from (select DICTYPEKEY,DICKEY,DICVALUE,RYBM,XM,XMPY,SZDZBDM from CF_DICTIONARY, VM_RYJBXX where DICTYPEKEY = 'leaderType' and DICKEY in (6)
and RYBM = #{rybm}
) d inner join ZZ_ZZQKXX dw on SUBSTR(d.SZDZBDM,1,12)=dw.DZZDM left join ( select zz2.DZZDM,zz2.DZZMC,fb2.ZZLB from ZZ_ZZQKXX zz2 inner join ZZ_ZZQKXXFB fb2 on zz2.DZZDM=fb2.DZZDM ) dw2 on SUBSTR(d.SZDZBDM,1,15)=dw2.DZZDM left join (select u.USERCODE,u.LEADERTYPE,count(*) as count from US_USERLEADER U where 1 = 1
and u.USERCODE = #{rybm}
and date_format(LEADERTIME,'%Y') = #{year} group by u.USERCODE,u.LEADERTYPE ) t on d.dickey = t.LEADERTYPE and d.RYBM = t.USERCODE
